//! `DV_IDENTIFIER` — identifiers of real-world entities.
//!
//! openEHR class: `DV_IDENTIFIER`, package `rm.data_types.basic`.
//! Inherits: `DATA_VALUE`.
//!
//! Type for representing identifiers of real-world entities. Typical
//! identifiers include drivers licence number, social security number,
//! veterans affairs number, prescription id, order id, and so on.
//!
//! `DV_IDENTIFIER` is used to represent any identifier of a real thing,
//! issued by some authority or agency.
//!
//! Misuse: `DV_IDENTIFIER` is not used to express identifiers generated by
//! the infrastructure to refer to information items; the types `OBJECT_ID`
//! and `OBJECT_REF` and subtypes are defined for this purpose.
use crate::data_types::data_value::DataValueApi;
use openehr_foundation::serde_support::{TypeName, TypeTag};
use serde::{Deserialize, Serialize};

/// Canonical `_type` discriminator string for this class, single-sourced
/// into its [`TypeName`] impl (ADR-002).
pub const TYPE_NAME: &str = "DV_IDENTIFIER";

/// `DV_IDENTIFIER` is a leaf, non-abstract class with four `String`
/// attributes, only one of which (`id`) is mandatory.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct DvIdentifier {
    /// Canonical `_type` discriminator (`"DV_IDENTIFIER"`), always
    /// serialized first (ADR-002).
    #[serde(rename = "_type", default = "TypeTag::new")]
    pub type_tag: TypeTag<Self>,

    /// `issuer`: `String` (`0..1`).
    ///
    /// Optional authority which issues the kind of id used in the id field
    /// of this object.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub issuer: Option<String>,

    /// `assigner`: `String` (`0..1`).
    ///
    /// Optional organisation that assigned the id to the item being
    /// identified.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub assigner: Option<String>,

    /// `id`: `String` (`1..1`).
    ///
    /// The identifier value. Often structured, according to the definition
    /// of the issuing authority's rules.
    ///
    /// Invariant `Id_valid`: `not id.is_empty`.
    ///
    /// TODO(port): invariant not yet enforced by a constructor/`Validate`
    /// impl; recorded here as a doc note pending the RM invariant framework
    /// (`.claude/rules/rm-transcription.md` "Invariants").
    pub id: String,

    /// `type`: `String` (`0..1`).
    ///
    /// Optional identifier type, such as "prescription", or "Social
    /// Security Number". One day a controlled vocabulary might be possible
    /// for this.
    ///
    /// PORT NOTE: field named `r#type` (raw identifier) since `type` is a
    /// Rust reserved keyword, mirroring the `OBJECT_REF.type` precedent in
    /// `crates/openehr-base/src/identification/object_ref.rs`. Now carries
    /// `#[serde(rename = "type")]` per that same precedent.
    #[serde(rename = "type", skip_serializing_if = "Option::is_none")]
    pub r#type: Option<String>,
}

impl TypeName for DvIdentifier {
    const NAME: &'static str = TYPE_NAME;
}

impl DvIdentifier {
    /// `Id_valid`: `not id.is_empty`.
    ///
    /// TODO(port): wire into a `Validate` impl (context + path + error
    /// accumulator) once the RM invariant framework lands; left as a plain
    /// boolean predicate for now, matching the foundation-types precedent
    /// for simple, non-nested, single-value invariants (see
    /// `[[project-time-types-precedent]]` item 5 in agent memory).
    pub fn invariant_id_valid(&self) -> bool {
        !self.id.is_empty()
    }
}

impl DataValueApi for DvIdentifier {
    fn type_name(&self) -> &'static str {
        TYPE_NAME
    }
}

